#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ObjectModPropertyValueType {
    Int,
    Float,
    Bool,
    String,
    FormIdInt,
    Enum,
    FormIdFloat,
    /// A value the definition does not name.
    Other(u8),
}

impl ObjectModPropertyValueType {
    /// The variant for a stored value.
    pub fn from_raw(raw: u8) -> Self {
        match raw {
            0 => Self::Int,
            1 => Self::Float,
            2 => Self::Bool,
            3 => Self::String,
            4 => Self::FormIdInt,
            5 => Self::Enum,
            6 => Self::FormIdFloat,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u8 {
        match self {
            Self::Int => 0,
            Self::Float => 1,
            Self::Bool => 2,
            Self::String => 3,
            Self::FormIdInt => 4,
            Self::Enum => 5,
            Self::FormIdFloat => 6,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for ObjectModPropertyValueType {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

impl Visit for ObjectModPropertyValueType {}

