#[derive(Debug, Clone, PartialEq, Default)]
pub struct ProjMuzzleFlashModel {
    /// `NAM1`, required.
    pub file_name: Option<Sub<ZString>>,
    /// `FLLD`, optional.
    pub light_layer: Option<Sub<ProjMuzzleFlashModelLightLayer>>,
}

impl ProjMuzzleFlashModel {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"NAM1",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FLLD",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.file_name,
                    subs,
                    *index,
                    "PROJ.MuzzleFlashModel.NAM1",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.light_layer,
                    subs,
                    *index,
                    "PROJ.MuzzleFlashModel.FLLD",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"NAM1", self.file_name.as_ref());
        emit(out, *b"FLLD", self.light_layer.as_ref());
    }
}

