#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProjSoundLevel {
    None,
    Silent,
    Quiet,
    Normal,
    Loud,
    VeryLoud,
    /// A value the definition does not name.
    Other(u32),
}

impl ProjSoundLevel {
    /// The variant for a stored value.
    pub fn from_raw(raw: u32) -> Self {
        match raw {
            0 => Self::None,
            1 => Self::Silent,
            2 => Self::Quiet,
            3 => Self::Normal,
            4 => Self::Loud,
            5 => Self::VeryLoud,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u32 {
        match self {
            Self::None => 0,
            Self::Silent => 1,
            Self::Quiet => 2,
            Self::Normal => 3,
            Self::Loud => 4,
            Self::VeryLoud => 5,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for ProjSoundLevel {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u32::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

impl Visit for ProjSoundLevel {}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct ProjRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<ProjObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `OPDS`, optional.
    pub object_palette_defaults: Option<Sub<ProjObjectPaletteDefaults>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<ProjTransforms>>,
    /// `SNTP`, optional.
    pub snap_template: Option<Sub<FormId>>,
    /// `SNBH`, optional.
    pub snap_behavior: Option<Sub<FormId>>,
    /// `DEFL`, optional.
    pub default_layer: Option<Sub<FormId>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Group `Model`, required.
    pub model: Option<Model>,
    /// Group `Destructible`, optional.
    pub destructible: Option<Destructible>,
    /// `DATA`, required.
    pub unused_data: Option<Sub<Empty>>,
    /// `PROD`, required.
    pub data: Option<Sub<ProjData>>,
    /// Group `MuzzleFlashModel`, required.
    pub muzzle_flash_model: Option<ProjMuzzleFlashModel>,
    /// `PRAS`, optional.
    pub active_sound: Option<Sub<SoundReference>>,
    /// `PRCS`, optional.
    pub countdown_end_sound: Option<Sub<SoundReference>>,
    /// `PRDS`, optional.
    pub disable_sound: Option<Sub<SoundReference>>,
    /// `VNAM`, required.
    pub sound_level: Option<Sub<ProjSoundLevel>>,
    /// `NAM3`, optional.
    pub curve_table: Option<Sub<FormId>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl ProjRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OPDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNTP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNBH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DEFL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: Model::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Destructible::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"PROD",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: ProjMuzzleFlashModel::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"PRAS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PRCS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PRDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"NAM3",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "PROJ.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "PROJ.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "PROJ.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "PROJ.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.object_palette_defaults,
                    subs,
                    *index,
                    "PROJ.OPDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.transforms, subs, *index, "PROJ.PTT2", ctx, extra)
                }
                Hit::Sub { member: 6, index } => put(
                    &mut self.snap_template,
                    subs,
                    *index,
                    "PROJ.SNTP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 7, index } => put(
                    &mut self.snap_behavior,
                    subs,
                    *index,
                    "PROJ.SNBH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => put(
                    &mut self.default_layer,
                    subs,
                    *index,
                    "PROJ.DEFL",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 9, index } => {
                    put(&mut self.xalg_flags, subs, *index, "PROJ.XALG", ctx, extra)
                }
                Hit::Group { member: 10, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 11, index } => {
                    put(&mut self.name, subs, *index, "PROJ.FULL", ctx, extra)
                }
                Hit::Group { member: 12, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                Hit::Group { member: 13, hits } if self.destructible.is_none() => {
                    let mut group = Destructible::default();
                    group.fill(hits, subs, ctx, extra);
                    self.destructible = Some(group);
                }
                Hit::Sub { member: 14, index } => {
                    put(&mut self.unused_data, subs, *index, "PROJ.DATA", ctx, extra)
                }
                Hit::Sub { member: 15, index } => {
                    put(&mut self.data, subs, *index, "PROJ.PROD", ctx, extra)
                }
                Hit::Group { member: 16, hits } if self.muzzle_flash_model.is_none() => {
                    let mut group = ProjMuzzleFlashModel::default();
                    group.fill(hits, subs, ctx, extra);
                    self.muzzle_flash_model = Some(group);
                }
                Hit::Sub { member: 17, index } => put(
                    &mut self.active_sound,
                    subs,
                    *index,
                    "PROJ.PRAS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => put(
                    &mut self.countdown_end_sound,
                    subs,
                    *index,
                    "PROJ.PRCS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 19, index } => put(
                    &mut self.disable_sound,
                    subs,
                    *index,
                    "PROJ.PRDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 20, index } => {
                    put(&mut self.sound_level, subs, *index, "PROJ.VNAM", ctx, extra)
                }
                Hit::Sub { member: 21, index } => {
                    put(&mut self.curve_table, subs, *index, "PROJ.NAM3", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"OPDS", self.object_palette_defaults.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        emit(out, *b"SNTP", self.snap_template.as_ref());
        emit(out, *b"SNBH", self.snap_behavior.as_ref());
        emit(out, *b"DEFL", self.default_layer.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        if let Some(group) = &self.model {
            group.emit(out);
        }
        if let Some(group) = &self.destructible {
            group.emit(out);
        }
        emit(out, *b"DATA", self.unused_data.as_ref());
        emit(out, *b"PROD", self.data.as_ref());
        if let Some(group) = &self.muzzle_flash_model {
            group.emit(out);
        }
        emit(out, *b"PRAS", self.active_sound.as_ref());
        emit(out, *b"PRCS", self.countdown_end_sound.as_ref());
        emit(out, *b"PRDS", self.disable_sound.as_ref());
        emit(out, *b"VNAM", self.sound_level.as_ref());
        emit(out, *b"NAM3", self.curve_table.as_ref());
    }
}

