#[derive(Debug, Clone, PartialEq, Default)]
pub struct Tes4Record {
    /// `HEDR`, required.
    pub header: Option<Sub<Tes4Header>>,
    /// `CNAM`, optional.
    pub author: Option<Sub<ZString>>,
    /// `SNAM`, optional.
    pub description: Option<Sub<ZString>>,
    /// Group `Master`, repeated.
    pub master: Vec<Tes4Master>,
    /// `ONAM`, optional.
    pub overridden_forms: Option<Sub<Tes4OverriddenForms>>,
    /// `INTV`, optional.
    pub tagify_count: Option<Sub<u32>>,
    /// `TNAM`, repeated.
    pub tnam: Vec<Sub<Bytes>>,
    /// `BNAM`, optional.
    pub bnam: Option<Sub<Bytes>>,
    /// `INCC`, optional.
    pub incc: Option<Sub<u32>>,
    /// `CHGL`, optional.
    pub chgl: Option<Sub<Bytes>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl Tes4Record {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"HEDR",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"CNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Tes4Master::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"INTV",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"TNAM",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"BNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"INCC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CHGL",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.header, subs, *index, "TES4.HEDR", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.author, subs, *index, "TES4.CNAM", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.description, subs, *index, "TES4.SNAM", ctx, extra)
                }
                Hit::Group { member: 3, hits } => {
                    let mut group = Tes4Master::default();
                    group.fill(hits, subs, ctx, extra);
                    self.master.push(group);
                }
                Hit::Sub { member: 4, index } => put(
                    &mut self.overridden_forms,
                    subs,
                    *index,
                    "TES4.ONAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => put(
                    &mut self.tagify_count,
                    subs,
                    *index,
                    "TES4.INTV",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 6, index } => {
                    push(&mut self.tnam, subs, *index, "TES4.TNAM", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.bnam, subs, *index, "TES4.BNAM", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.incc, subs, *index, "TES4.INCC", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.chgl, subs, *index, "TES4.CHGL", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"HEDR", self.header.as_ref());
        emit(out, *b"CNAM", self.author.as_ref());
        emit(out, *b"SNAM", self.description.as_ref());
        for group in &self.master {
            group.emit(out);
        }
        emit(out, *b"ONAM", self.overridden_forms.as_ref());
        emit(out, *b"INTV", self.tagify_count.as_ref());
        for value in &self.tnam {
            emit(out, *b"TNAM", Some(value));
        }
        emit(out, *b"BNAM", self.bnam.as_ref());
        emit(out, *b"INCC", self.incc.as_ref());
        emit(out, *b"CHGL", self.chgl.as_ref());
    }
}

impl Visit for Tes4Record {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.overridden_forms, "TES4.ONAM", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.overridden_forms, "TES4.ONAM", out);
    }
}

impl Tes4Record {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"TES4";
    /// Record-header flag.
    pub const FLAG_MASTER: u32 = 0x1;
    /// Record-header flag.
    pub const FLAG_LOCALIZED: u32 = 0x80;

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("TES4", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("TES4", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("TES4", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("TES4", &mut out);
        out
    }
}

