/// A decoded record of any type the schema defines (boxed: record structs are large).
#[derive(Debug, Clone, PartialEq)]
pub enum Record {
    Amdl(Box<AmdlRecord>),
    Ammo(Box<AmmoRecord>),
    Cobj(Box<CobjRecord>),
    Glob(Box<GlobRecord>),
    Gmst(Box<GmstRecord>),
    Kywd(Box<KywdRecord>),
    Omod(Box<OmodRecord>),
    Proj(Box<ProjRecord>),
    Tes4(Box<Tes4Record>),
    Weap(Box<WeapRecord>),
    Zoom(Box<ZoomRecord>),
}

/// The member list of every defined record type, by signature.
pub const RECORDS: &[(Sig, &[MemberDesc])] = &[
    (*b"AMDL", AmdlRecord::MEMBERS),
    (*b"AMMO", AmmoRecord::MEMBERS),
    (*b"COBJ", CobjRecord::MEMBERS),
    (*b"GLOB", GlobRecord::MEMBERS),
    (*b"GMST", GmstRecord::MEMBERS),
    (*b"KYWD", KywdRecord::MEMBERS),
    (*b"OMOD", OmodRecord::MEMBERS),
    (*b"PROJ", ProjRecord::MEMBERS),
    (*b"TES4", Tes4Record::MEMBERS),
    (*b"WEAP", WeapRecord::MEMBERS),
    (*b"ZOOM", ZoomRecord::MEMBERS),
];

impl Record {
    /// Decodes a record body of type `signature`; `None` when the schema has no
    /// definition for it (the container keeps such records raw).
    pub fn decode(signature: Sig, subs: &[RawSub<'_>], ctx: Ctx) -> Option<Self> {
        Some(match &signature {
            b"AMDL" => Self::Amdl(Box::new(AmdlRecord::decode(subs, ctx))),
            b"AMMO" => Self::Ammo(Box::new(AmmoRecord::decode(subs, ctx))),
            b"COBJ" => Self::Cobj(Box::new(CobjRecord::decode(subs, ctx))),
            b"GLOB" => Self::Glob(Box::new(GlobRecord::decode(subs, ctx))),
            b"GMST" => Self::Gmst(Box::new(GmstRecord::decode(subs, ctx))),
            b"KYWD" => Self::Kywd(Box::new(KywdRecord::decode(subs, ctx))),
            b"OMOD" => Self::Omod(Box::new(OmodRecord::decode(subs, ctx))),
            b"PROJ" => Self::Proj(Box::new(ProjRecord::decode(subs, ctx))),
            b"TES4" => Self::Tes4(Box::new(Tes4Record::decode(subs, ctx))),
            b"WEAP" => Self::Weap(Box::new(WeapRecord::decode(subs, ctx))),
            b"ZOOM" => Self::Zoom(Box::new(ZoomRecord::decode(subs, ctx))),
            _ => return None,
        })
    }

    /// Encodes the record body.
    pub fn encode(&self) -> Vec<OwnedSub> {
        match self {
            Self::Amdl(record) => record.encode(),
            Self::Ammo(record) => record.encode(),
            Self::Cobj(record) => record.encode(),
            Self::Glob(record) => record.encode(),
            Self::Gmst(record) => record.encode(),
            Self::Kywd(record) => record.encode(),
            Self::Omod(record) => record.encode(),
            Self::Proj(record) => record.encode(),
            Self::Tes4(record) => record.encode(),
            Self::Weap(record) => record.encode(),
            Self::Zoom(record) => record.encode(),
        }
    }

    /// The record signature.
    pub fn signature(&self) -> Sig {
        match self {
            Self::Amdl(_) => AmdlRecord::SIGNATURE,
            Self::Ammo(_) => AmmoRecord::SIGNATURE,
            Self::Cobj(_) => CobjRecord::SIGNATURE,
            Self::Glob(_) => GlobRecord::SIGNATURE,
            Self::Gmst(_) => GmstRecord::SIGNATURE,
            Self::Kywd(_) => KywdRecord::SIGNATURE,
            Self::Omod(_) => OmodRecord::SIGNATURE,
            Self::Proj(_) => ProjRecord::SIGNATURE,
            Self::Tes4(_) => Tes4Record::SIGNATURE,
            Self::Weap(_) => WeapRecord::SIGNATURE,
            Self::Zoom(_) => ZoomRecord::SIGNATURE,
        }
    }

    /// Every FormID-typed value with its path (see each record's `form_ids`).
    pub fn form_ids(&self) -> FormIds<'_> {
        match self {
            Self::Amdl(record) => record.form_ids(),
            Self::Ammo(record) => record.form_ids(),
            Self::Cobj(record) => record.form_ids(),
            Self::Glob(record) => record.form_ids(),
            Self::Gmst(record) => record.form_ids(),
            Self::Kywd(record) => record.form_ids(),
            Self::Omod(record) => record.form_ids(),
            Self::Proj(record) => record.form_ids(),
            Self::Tes4(record) => record.form_ids(),
            Self::Weap(record) => record.form_ids(),
            Self::Zoom(record) => record.form_ids(),
        }
    }

    /// Every FormID-typed value with its path, mutably.
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        match self {
            Self::Amdl(record) => record.form_ids_mut(),
            Self::Ammo(record) => record.form_ids_mut(),
            Self::Cobj(record) => record.form_ids_mut(),
            Self::Glob(record) => record.form_ids_mut(),
            Self::Gmst(record) => record.form_ids_mut(),
            Self::Kywd(record) => record.form_ids_mut(),
            Self::Omod(record) => record.form_ids_mut(),
            Self::Proj(record) => record.form_ids_mut(),
            Self::Tes4(record) => record.form_ids_mut(),
            Self::Weap(record) => record.form_ids_mut(),
            Self::Zoom(record) => record.form_ids_mut(),
        }
    }

    /// Every lstring value with its path (see each record's `lstrings`).
    pub fn lstrings(&self) -> LStrings<'_> {
        match self {
            Self::Amdl(record) => record.lstrings(),
            Self::Ammo(record) => record.lstrings(),
            Self::Cobj(record) => record.lstrings(),
            Self::Glob(record) => record.lstrings(),
            Self::Gmst(record) => record.lstrings(),
            Self::Kywd(record) => record.lstrings(),
            Self::Omod(record) => record.lstrings(),
            Self::Proj(record) => record.lstrings(),
            Self::Tes4(record) => record.lstrings(),
            Self::Weap(record) => record.lstrings(),
            Self::Zoom(record) => record.lstrings(),
        }
    }

    /// Every lstring value with its path, mutably.
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        match self {
            Self::Amdl(record) => record.lstrings_mut(),
            Self::Ammo(record) => record.lstrings_mut(),
            Self::Cobj(record) => record.lstrings_mut(),
            Self::Glob(record) => record.lstrings_mut(),
            Self::Gmst(record) => record.lstrings_mut(),
            Self::Kywd(record) => record.lstrings_mut(),
            Self::Omod(record) => record.lstrings_mut(),
            Self::Proj(record) => record.lstrings_mut(),
            Self::Tes4(record) => record.lstrings_mut(),
            Self::Weap(record) => record.lstrings_mut(),
            Self::Zoom(record) => record.lstrings_mut(),
        }
    }

    /// Subrecords the definition did not place or could not decode, with their indexes
    /// in the body as read (empty when every subrecord decoded into a typed member).
    pub fn extra(&self) -> &[(usize, OwnedSub)] {
        match self {
            Self::Amdl(record) => &record.extra,
            Self::Ammo(record) => &record.extra,
            Self::Cobj(record) => &record.extra,
            Self::Glob(record) => &record.extra,
            Self::Gmst(record) => &record.extra,
            Self::Kywd(record) => &record.extra,
            Self::Omod(record) => &record.extra,
            Self::Proj(record) => &record.extra,
            Self::Tes4(record) => &record.extra,
            Self::Weap(record) => &record.extra,
            Self::Zoom(record) => &record.extra,
        }
    }
}
